package com.tdea.librotdea.entity;

import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import java.time.LocalDate;
import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

/**
 * Book available in the library catalog.
 *
 * <p>Getters, setters and constructors are generated by Lombok:
 * <ul>
 *   <li>{@code Book()} – empty constructor required by JPA.</li>
 *   <li>{@code Book(id, name, isbnNumber, author, publishDate, price, type)} – full constructor.</li>
 *   <li>{@code getX()} / {@code setX(value)} for every field; the field Javadoc below
 *       is copied by Lombok to the generated accessors.</li>
 * </ul>
 */
@Entity
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
public class Book {

    /** Unique identifier, generated by the database (IDENTITY). */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** Title of the book. */
    private String name;

    /** ISBN code of the book. */
    private String isbnNumber;

    /** Author of the book. */
    private String author;

    /** Publication date. */
    private LocalDate publishDate;

    /** Sale price. */
    private Double price;

    /** Publication format, stored as its name (e.g. {@code "EBOOK"}). */
    @Enumerated(EnumType.STRING)
    private BookType type;
}
